 * Tunable blocking parameters.
 *
 * These control the 2D tiling used in the main kernel to improve cache
 * locality and to expose long, unit-stride inner loops for the compiler
 * to vectorize. They can be overridden at compile time with -D flags.
 * ------------------------------------------------------------------ */
#ifndef GRAMSCHMIDT_I_BLOCK
# define GRAMSCHMIDT_I_BLOCK 64   /* tile size along i (rows)    */
#endif
#ifndef GRAMSCHMIDT_J_BLOCK
# define GRAMSCHMIDT_J_BLOCK 32   /* tile size along j (columns) */
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
