   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Create local restrict-qualified views of the 2D arrays.
     Using VLA-based pointer types gives the compiler exact
     row lengths (n) and tells it that A_, R_, and Q_ do not
     alias each other, which helps optimization and vectorization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict R_)[n] = R;
  DATA_TYPE (*restrict Q_)[n] = Q;

#pragma scop
  /* Outer loop over columns k: this must remain sequential because
     each step uses the A and R produced by all previous steps. */
  for (k = 0; k < _PB_N; k++)
    {
      /* 1) Compute squared 2-norm of k-th column of A. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE aik = A_[i][k];
        nrm += aik * aik;
      }

      /* 2) Set diagonal of R and normalize column k into Q.
            We precompute the reciprocal of R[k][k] so that
            Q[i][k] uses a multiplication instead of a division. */
      R_[k][k] = SQRT_FUN(nrm);

      DATA_TYPE inv_rkk = SCALAR_VAL(1.0) / R_[k][k];

      for (i = 0; i < _PB_M; i++)
        Q_[i][k] = A_[i][k] * inv_rkk;

      /* 3) Initialize the k-th row of R for trailing columns j > k. */
      for (j = k + 1; j < _PB_N; j++)
        R_[k][j] = SCALAR_VAL(0.0);

      /* 4) Build R[k, j] = Q[:,k]^T * A[:,j] for all j > k.
             We switch to an i-outer, j-inner ordering and apply
             simple 2D blocking:
               - A is row-major, so A_[i][j] is contiguous in j.
               - R is also row-major, so R_[k][j] is contiguous in j.
             The innermost j-loop is thus unit-stride and very
             friendly to hardware prefetchers and SIMD. */
      for (int ii = 0; ii < _PB_M; ii += GRAMSCHMIDT_I_BLOCK)
      {
        int i_end = ii + GRAMSCHMIDT_I_BLOCK;
        if (i_end > _PB_M)
          i_end = _PB_M;

        for (int jj = k + 1; jj < _PB_N; jj += GRAMSCHMIDT_J_BLOCK)
        {
          int j_end = jj + GRAMSCHMIDT_J_BLOCK;
          if (j_end > _PB_N)
            j_end = _PB_N;

          for (i = ii; i < i_end; i++)
          {
            DATA_TYPE qik = Q_[i][k];

            for (j = jj; j < j_end; j++)
              R_[k][j] += qik * A_[i][j];
          }
        }
      }

      /* 5) Update trailing columns of A:
             A[:,j] = A[:,j] - Q[:,k] * R[k,j]  for all j > k.
             We reuse the same blocked, row-major-friendly traversal
             pattern as above. */
      for (int ii = 0; ii < _PB_M; ii += GRAMSCHMIDT_I_BLOCK)
      {
        int i_end = ii + GRAMSCHMIDT_I_BLOCK;
        if (i_end > _PB_M)
          i_end = _PB_M;

        for (int jj = k + 1; jj < _PB_N; jj += GRAMSCHMIDT_J_BLOCK)
        {
          int j_end = jj + GRAMSCHMIDT_J_BLOCK;
          if (j_end > _PB_N)
            j_end = _PB_N;

          for (i = ii; i < i_end; i++)
          {
            DATA_TYPE qik = Q_[i][k];

            for (j = jj; j < j_end; j++)
              A_[i][j] -= qik * R_[k][j];
          }
        }
      }
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(R,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(Q,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(R),
	      POLYBENCH_ARRAY(Q));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gramschmidt (m, n,
		      POLYBENCH_ARRAY(A),
		      POLYBENCH_ARRAY(R),
		      POLYBENCH_ARRAY(Q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(R), POLYBENCH_ARRAY(Q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(R);
  POLYBENCH_FREE_ARRAY(Q);

  return 0;
}
