  /* Tile indices for cache blocking in the (i,j) plane. */
  int I, J;

  /* Tiling parameters. These are chosen to keep one (I,J) tile
     of A and the corresponding slice of R in L1 cache on typical
     x86-64 machines. Adjust as needed. */
  const int tile_i = 64; /* rows  */
  const int tile_j = 32; /* cols  */

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* 1. Compute squared 2-norm of k-th column of A. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];

      /* 2. Compute R[k][k] and its reciprocal.
         We replace M divisions by one division + M multiplications:
           Q[i][k] = A[i][k] / R[k][k]
         becomes
           Q[i][k] = A[i][k] * inv_rkk
       */
      DATA_TYPE rkk = SQRT_FUN(nrm);
      DATA_TYPE inv_rkk = SCALAR_VAL(1.0) / rkk;
      R[k][k] = rkk;

      /* Normalize k-th column to obtain Q[:,k]. */
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] * inv_rkk;

      /* 3. Initialize the rest of row k of R.  This is kept as a
         simple contiguous sweep for good cache behavior on R. */
      for (j = k + 1; j < _PB_N; j++)
        R[k][j] = SCALAR_VAL(0.0);

      /* 4. Build R[k, j] = <Q[:,k], A[:,j]> for all j>k.
         Original code (column-wise, poor for row-major A):
             for (j = k+1; j < N; ++j) {
               R[k][j] = 0;
               for (i = 0; i < M; ++i)
                 R[k][j] += Q[i][k] * A[i][j];
             }
         We reorganize this as a tiled, row-major-friendly traversal:

           for I in tiles of rows
             for i in I-tile
               qki = Q[i][k];                // reused across all columns
               for J in tiles of columns j>k
                 for j in J-tile
                   R[k][j] += qki * A[i][j];

         For each fixed (k,j), the sequence of updates to R[k][j] over i
         is identical to the original program (same i-order), so floating
         point results are bitwise identical for R.
      */
      for (I = 0; I < _PB_M; I += tile_i)
      {
        int i_end = I + tile_i;
        if (i_end > _PB_M)
          i_end = _PB_M;

        for (i = I; i < i_end; i++)
        {
          DATA_TYPE qki = Q[i][k];

          for (J = k + 1; J < _PB_N; J += tile_j)
          {
